// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {
        // Admissible domain: the requested new owner is not the contract itself
        // (if it were, P and M would coincidentally agree). The caller is the
        // deployer (this test contract), which is c.owner(), so the call succeeds.
        vm.assume(newOwner != address(c));

        c.setOwner(newOwner);

        // Rule: for any admissible requested address, owner becomes exactly that address.
        assertTrue(c.owner() == newOwner, "owner must equal requested address");
    }
}
